package it.gruppoinit.pal.gp.core.domain;

import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.Id;
import javax.persistence.Table;
import javax.persistence.Transient;

import org.hibernate.validator.Length;

/**
 * RiFormegiuridiche generated by hbm2java
 */
@Entity
@Table(name = "RI_FORMEGIURIDICHE")
public class RiFormegiuridiche implements java.io.Serializable {

    private static final long serialVersionUID = -4621154345706583444L;
    private String codice;
    private String descrizione;

    public RiFormegiuridiche() {

    }

    @Id
    @Column(name = "CODICE", unique = true, nullable = false, length = 5)
    public String getCodice() {

	return this.codice;
    }

    public void setCodice(String codice) {

	this.codice = codice;
    }

    @Length(max = 150)
    @Column(name = "DESCRIZIONE", length = 150)
    public String getDescrizione() {

	return this.descrizione;
    }

    public void setDescrizione(String descrizione) {

	this.descrizione = descrizione;
    }

    @Transient
    public String getDescrizioneEstesa() {

	if (getCodice() != null) {
	    return getDescrizione() + " (" + getCodice() + ")";
	}
	return getDescrizione();
    }
}
